BEGIN TRANSACTION;
CREATE TABLE access_requests (
	id TEXT NOT NULL, 
	requester_id TEXT NOT NULL, 
	request_type TEXT NOT NULL, 
	target_details TEXT NOT NULL, 
	status TEXT NOT NULL, 
	reviewed_by TEXT, 
	review_note TEXT, 
	created_at TEXT NOT NULL, 
	reviewed_at TEXT, 
	PRIMARY KEY (id), 
	FOREIGN KEY(requester_id) REFERENCES users (id), 
	FOREIGN KEY(reviewed_by) REFERENCES users (id)
);
CREATE TABLE announcements (
	id TEXT NOT NULL, 
	title TEXT NOT NULL, 
	content TEXT NOT NULL, 
	author_id TEXT NOT NULL, 
	target_scope TEXT NOT NULL, 
	priority TEXT NOT NULL, 
	is_active BOOLEAN, 
	expires_at TEXT, 
	created_at TEXT NOT NULL, 
	PRIMARY KEY (id), 
	FOREIGN KEY(author_id) REFERENCES users (id)
);
CREATE TABLE assignment_submissions (
	id TEXT NOT NULL, 
	assignment_id TEXT NOT NULL, 
	student_id TEXT NOT NULL, 
	submitted_at TEXT NOT NULL, 
	file_name TEXT, 
	file_path TEXT, 
	notes TEXT, 
	marks FLOAT, 
	graded_at TEXT, 
	feedback TEXT, 
	PRIMARY KEY (id), 
	FOREIGN KEY(assignment_id) REFERENCES assignments (id), 
	FOREIGN KEY(student_id) REFERENCES students (student_id)
);
CREATE TABLE assignments (
	id TEXT NOT NULL, 
	subject_id TEXT NOT NULL, 
	class_section_id TEXT NOT NULL, 
	teacher_id TEXT NOT NULL, 
	title TEXT NOT NULL, 
	description TEXT, 
	max_marks FLOAT, 
	due_date TEXT NOT NULL, 
	is_active BOOLEAN, 
	created_at TEXT NOT NULL, 
	PRIMARY KEY (id), 
	FOREIGN KEY(subject_id) REFERENCES subjects (id), 
	FOREIGN KEY(class_section_id) REFERENCES class_sections (id), 
	FOREIGN KEY(teacher_id) REFERENCES users (id)
);
CREATE TABLE attendance (
	id TEXT NOT NULL, 
	student_id TEXT, 
	classroom_id TEXT NOT NULL, 
	subject_id TEXT, 
	session_date TEXT NOT NULL, 
	timestamp TEXT NOT NULL, 
	status TEXT NOT NULL, 
	confidence FLOAT, 
	is_manual_override BOOLEAN NOT NULL, 
	override_note TEXT, 
	created_at TEXT NOT NULL, 
	PRIMARY KEY (id), 
	CONSTRAINT uq_attendance_student_day_subject_status UNIQUE (student_id, session_date, subject_id, status) ON CONFLICT IGNORE, 
	FOREIGN KEY(student_id) REFERENCES students (student_id), 
	FOREIGN KEY(classroom_id) REFERENCES classrooms (classroom_id), 
	FOREIGN KEY(subject_id) REFERENCES subjects (id)
);
CREATE TABLE audit_logs (
	id TEXT NOT NULL, 
	user_id TEXT NOT NULL, 
	action TEXT NOT NULL, 
	target_type TEXT, 
	target_id TEXT, 
	details TEXT, 
	ip_address TEXT, 
	created_at TEXT NOT NULL, 
	PRIMARY KEY (id), 
	FOREIGN KEY(user_id) REFERENCES users (id)
);
CREATE TABLE class_sections (
	id TEXT NOT NULL, 
	department_id TEXT NOT NULL, 
	name TEXT NOT NULL, 
	code TEXT NOT NULL, 
	semester TEXT, 
	is_active BOOLEAN, 
	created_at TEXT NOT NULL, 
	PRIMARY KEY (id), 
	FOREIGN KEY(department_id) REFERENCES departments (id), 
	UNIQUE (code)
);
CREATE TABLE classrooms (
	classroom_id TEXT NOT NULL, 
	name TEXT NOT NULL, 
	PRIMARY KEY (classroom_id)
);
CREATE TABLE departments (
	id TEXT NOT NULL, 
	school_id TEXT NOT NULL, 
	name TEXT NOT NULL, 
	code TEXT NOT NULL, 
	is_active BOOLEAN, 
	created_at TEXT NOT NULL, 
	PRIMARY KEY (id), 
	FOREIGN KEY(school_id) REFERENCES schools (id), 
	UNIQUE (code)
);
CREATE TABLE interventions (
	id TEXT NOT NULL, 
	mentor_id TEXT NOT NULL, 
	student_id TEXT NOT NULL, 
	type TEXT NOT NULL, 
	notes TEXT, 
	outcome TEXT, 
	created_at TEXT NOT NULL, 
	PRIMARY KEY (id), 
	FOREIGN KEY(mentor_id) REFERENCES users (id), 
	FOREIGN KEY(student_id) REFERENCES students (student_id)
);
CREATE TABLE mentor_assignments (
	id TEXT NOT NULL, 
	mentor_id TEXT NOT NULL, 
	student_id TEXT NOT NULL, 
	assigned_at TEXT NOT NULL, 
	is_active BOOLEAN, 
	PRIMARY KEY (id), 
	FOREIGN KEY(mentor_id) REFERENCES users (id), 
	FOREIGN KEY(student_id) REFERENCES students (student_id)
);
CREATE TABLE notifications (
	id TEXT NOT NULL, 
	user_id TEXT NOT NULL, 
	title TEXT NOT NULL, 
	message TEXT NOT NULL, 
	type TEXT NOT NULL, 
	is_read BOOLEAN, 
	link TEXT, 
	created_at TEXT NOT NULL, 
	PRIMARY KEY (id), 
	FOREIGN KEY(user_id) REFERENCES users (id)
);
CREATE TABLE parent_alerts (
	id TEXT NOT NULL, 
	student_id TEXT NOT NULL, 
	parent_contact_id TEXT NOT NULL, 
	alert_type TEXT NOT NULL, 
	message TEXT NOT NULL, 
	channel TEXT NOT NULL, 
	status TEXT NOT NULL, 
	sent_at TEXT, 
	created_at TEXT NOT NULL, 
	PRIMARY KEY (id), 
	FOREIGN KEY(student_id) REFERENCES students (student_id), 
	FOREIGN KEY(parent_contact_id) REFERENCES parent_contacts (id)
);
CREATE TABLE parent_contacts (
	id TEXT NOT NULL, 
	student_id TEXT NOT NULL, 
	parent_name TEXT NOT NULL, 
	relation TEXT NOT NULL, 
	phone TEXT, 
	email TEXT, 
	is_primary BOOLEAN, 
	alert_enabled BOOLEAN, 
	created_at TEXT NOT NULL, 
	PRIMARY KEY (id), 
	FOREIGN KEY(student_id) REFERENCES students (student_id)
);
CREATE TABLE risk_flags (
	id TEXT NOT NULL, 
	student_id TEXT NOT NULL, 
	risk_level TEXT NOT NULL, 
	reasons TEXT NOT NULL, 
	confidence TEXT NOT NULL, 
	calculated_at TEXT NOT NULL, 
	created_at TEXT NOT NULL, 
	PRIMARY KEY (id), 
	FOREIGN KEY(student_id) REFERENCES students (student_id)
);
CREATE TABLE schools (
	id TEXT NOT NULL, 
	name TEXT NOT NULL, 
	code TEXT NOT NULL, 
	is_active BOOLEAN, 
	created_at TEXT NOT NULL, 
	PRIMARY KEY (id), 
	UNIQUE (code)
);
CREATE TABLE scores (
	id TEXT NOT NULL, 
	student_id TEXT NOT NULL, 
	subject TEXT NOT NULL, 
	score FLOAT NOT NULL, 
	max_score FLOAT NOT NULL, 
	date TEXT NOT NULL, 
	created_at TEXT NOT NULL, 
	PRIMARY KEY (id), 
	FOREIGN KEY(student_id) REFERENCES students (student_id)
);
CREATE TABLE semester_results (
	id TEXT NOT NULL, 
	student_id TEXT NOT NULL, 
	subject_id TEXT NOT NULL, 
	semester TEXT NOT NULL, 
	academic_year TEXT NOT NULL, 
	marks_obtained FLOAT NOT NULL, 
	max_marks FLOAT NOT NULL, 
	grade TEXT, 
	credits FLOAT, 
	result TEXT NOT NULL, 
	declared_at TEXT, 
	created_at TEXT NOT NULL, 
	PRIMARY KEY (id), 
	FOREIGN KEY(student_id) REFERENCES students (student_id), 
	FOREIGN KEY(subject_id) REFERENCES subjects (id)
);
CREATE TABLE students (
	student_id TEXT NOT NULL, 
	name TEXT NOT NULL, 
	class TEXT NOT NULL, 
	classroom_id TEXT NOT NULL, 
	embedding TEXT, 
	enrolled_at TEXT, 
	is_active BOOLEAN NOT NULL, 
	created_at TEXT NOT NULL, 
	usn TEXT, 
	usn_updated BOOLEAN NOT NULL, 
	phone TEXT, 
	extracurricular TEXT, 
	PRIMARY KEY (student_id), 
	FOREIGN KEY(classroom_id) REFERENCES classrooms (classroom_id)
);
CREATE TABLE study_materials (
	id TEXT NOT NULL, 
	subject_id TEXT NOT NULL, 
	class_section_id TEXT, 
	uploaded_by TEXT NOT NULL, 
	title TEXT NOT NULL, 
	description TEXT, 
	file_name TEXT NOT NULL, 
	file_path TEXT NOT NULL, 
	file_size INTEGER, 
	file_type TEXT, 
	created_at TEXT NOT NULL, 
	PRIMARY KEY (id), 
	FOREIGN KEY(subject_id) REFERENCES subjects (id), 
	FOREIGN KEY(class_section_id) REFERENCES class_sections (id), 
	FOREIGN KEY(uploaded_by) REFERENCES users (id)
);
CREATE TABLE subjects (
	id TEXT NOT NULL, 
	department_id TEXT NOT NULL, 
	name TEXT NOT NULL, 
	code TEXT NOT NULL, 
	semester TEXT, 
	created_at TEXT NOT NULL, 
	PRIMARY KEY (id), 
	FOREIGN KEY(department_id) REFERENCES departments (id)
);
CREATE TABLE teacher_subjects (
	id TEXT NOT NULL, 
	teacher_id TEXT NOT NULL, 
	subject_id TEXT NOT NULL, 
	class_section_id TEXT NOT NULL, 
	assigned_at TEXT NOT NULL, 
	is_active BOOLEAN, 
	PRIMARY KEY (id), 
	FOREIGN KEY(teacher_id) REFERENCES users (id), 
	FOREIGN KEY(subject_id) REFERENCES subjects (id), 
	FOREIGN KEY(class_section_id) REFERENCES class_sections (id)
);
CREATE TABLE timetable_slots (
	id TEXT NOT NULL, 
	class_section_id TEXT NOT NULL, 
	subject_id TEXT NOT NULL, 
	teacher_id TEXT, 
	day_of_week INTEGER NOT NULL, 
	start_time TEXT NOT NULL, 
	end_time TEXT NOT NULL, 
	room TEXT, 
	is_active BOOLEAN, 
	created_at TEXT NOT NULL, 
	PRIMARY KEY (id), 
	FOREIGN KEY(class_section_id) REFERENCES class_sections (id), 
	FOREIGN KEY(subject_id) REFERENCES subjects (id), 
	FOREIGN KEY(teacher_id) REFERENCES users (id)
);
CREATE TABLE users (
	id TEXT NOT NULL, 
	name TEXT NOT NULL, 
	email TEXT NOT NULL, 
	password_hash TEXT NOT NULL, 
	role TEXT NOT NULL, 
	is_active BOOLEAN NOT NULL, 
	last_login_at TEXT, 
	created_at TEXT NOT NULL, 
	school_id TEXT, 
	department_id TEXT, 
	phone TEXT, 
	profile_photo_url TEXT, 
	theme_preference TEXT, 
	custom_permissions TEXT, 
	PRIMARY KEY (id), 
	UNIQUE (email), 
	FOREIGN KEY(school_id) REFERENCES schools (id), 
	FOREIGN KEY(department_id) REFERENCES departments (id)
);
CREATE INDEX ix_scores_student_date ON scores (student_id, date);
CREATE INDEX ix_risk_student_calc ON risk_flags (student_id, calculated_at);
CREATE INDEX ix_attendance_student_date ON attendance (student_id, session_date);
CREATE INDEX ix_attendance_classroom_date ON attendance (classroom_id, session_date);
CREATE INDEX ix_attendance_subject ON attendance (subject_id, session_date);
COMMIT;